import sys
from itertools import combinations

input = sys.stdin.read().split()
n = int(input[0])
a = list(map(int, input[1:]))

def find_division(n, a):
    total_sum = sum(a)
    for k in range(1, n):
        for indices in combinations(range(n), k):
            grigory_sum = sum(a[i] for i in indices)
            andrew_sum = total_sum - grigory_sum
            if grigory_sum != andrew_sum:
                return k, indices
    return -1, []

k, indices = find_division(n, a)
if k == -1:
    print(-1)
else:
    print(k)
    print(' '.join(str(i + 1) for i in indices))
